<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../../includes/cufa_fase2.php';validarPermiso('ver_actas');
try{$f=cufaFiltros();$materia=cufaId($_GET,['materia_id']);$estado=is_string($_GET['estado']??null)?$_GET['estado']:'';}catch(Throwable $e){cufaError($e);return;}
$where=[];$args=[];foreach(['periodo_id'=>'a.periodo_id','grupo_id'=>'a.grupo_id','carrera_id'=>'g.carrera_id'] as $k=>$col)if($f[$k]){$where[]=$col.'=?';$args[]=$f[$k];}
if($materia){$where[]='a.materia_id=?';$args[]=$materia;}if($estado!==''){$where[]='a.estado=?';$args[]=$estado;}
$s=$pdo->prepare('SELECT a.*,m.nombre materia,g.nombre grupo,p.nombre periodo,c.nombre carrera FROM actas a LEFT JOIN materias m ON m.id=a.materia_id LEFT JOIN grupos g ON g.id=a.grupo_id LEFT JOIN periodos p ON p.id=a.periodo_id LEFT JOIN carreras c ON c.id=g.carrera_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.id DESC');$s->execute($args);$actas=$s->fetchAll();
?>
<h1 class="text-3xl font-bold mb-6">Actas oficiales</h1><p class="mb-6">Consulta de actas existentes. Sus notas congeladas y estados históricos se conservan. Habilitar generación no cambia estos documentos.</p>
<?php cufaFiltrosHtml($pdo,$f,'actas'); ?>
<form method="GET" class="bg-white p-6 rounded-3xl shadow mb-6 flex flex-wrap gap-4"><input type="hidden" name="modulo" value="actas"><?php foreach($f as $k=>$v): ?><input type="hidden" name="<?= $k ?>" value="<?= cufaEsc($v) ?>"><?php endforeach; ?><label>Asignatura<select name="materia_id" class="border p-3 rounded-xl"><option value="">Todas</option><?php foreach($pdo->query('SELECT id,nombre FROM materias ORDER BY nombre')->fetchAll() as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $materia==$m['id']?'selected':'' ?>><?= cufaEsc($m['nombre']) ?></option><?php endforeach; ?></select></label><label>Estado<select name="estado" class="border p-3 rounded-xl"><option value="">Todos</option><?php foreach(['generada','abierta','cerrada'] as $st): ?><option value="<?= $st ?>" <?= $estado===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select></label><button class="bg-purple-600 text-white px-5 rounded-xl">Aplicar</button></form>
<div class="overflow-x-auto bg-white rounded-3xl shadow"><table class="w-full"><tr class="bg-purple-200"><th class="p-4">Código</th><th>Asignatura / carrera</th><th>Grupo / periodo</th><th>Estado histórico</th><th>Consulta</th></tr><?php foreach($actas as $a): ?><tr class="border-t"><td class="p-4"><?= cufaEsc($a['codigo']?:'ACTA-'.$a['id']) ?></td><td><?= cufaEsc($a['materia']??'Sin referencia') ?><br><small><?= cufaEsc($a['carrera']??'Histórica') ?></small></td><td><?= cufaEsc(($a['grupo']??'Sin referencia').' / '.($a['periodo']??'Sin referencia')) ?></td><td><?= cufaEsc($a['estado']) ?></td><td class="p-4"><a class="text-purple-700 underline" href="<?= cufaEsc(cufaPanel('ver_acta',['id'=>$a['id']])) ?>">Abrir / imprimir</a> · <a class="text-purple-700 underline" href="<?= cufaEsc(cufaUrl('modules/control_escolar/pdf_acta.php',['id'=>$a['id'],'descargar'=>1])) ?>">Descargar PDF</a></td></tr><?php endforeach; ?></table></div>
<?php if(!$actas): ?><p class="p-6">Sin actas para los filtros seleccionados.</p><?php endif; ?>
